import React, { useContext, useState } from 'react';
import { Link } from 'react-router-dom';
import { ParticipantContext } from '../context/ParticipantContext';
import { PrizeContext } from '../context/PrizeContext';
import ParticipantList from '../components/ParticipantList';
import PasswordModal from '../components/modals/PasswordModal';
import ExportParticipants from '../components/ExportParticipants';

const AdminPage = () => {
  const { participants, loading: participantsLoading, error: participantsError, refreshParticipants, deleteAllParticipants } = useContext(ParticipantContext);
  const { prizes, loading: prizesLoading, error: prizesError, refreshPrizes, resetPrizes } = useContext(PrizeContext);
  
  const [refreshing, setRefreshing] = useState(false);
  const [clearing, setClearing] = useState(false);
  const [resettingPrizes, setResettingPrizes] = useState(false);
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [passwordAction, setPasswordAction] = useState('');

  const handleRefresh = async () => {
    setRefreshing(true);
    await refreshParticipants();
    await refreshPrizes();
    setRefreshing(false);
  };

  const handleClearParticipants = async () => {
    // Önce bir onay iste
    const confirmDelete = window.confirm('Tüm katılımcıları silmek istediğinizden emin misiniz? Bu işlem geri alınamaz.');
    
    if (!confirmDelete) {
      return;
    }
    
    // Şifre modalını göster
    setPasswordAction('clearParticipants');
    setShowPasswordModal(true);
  };
  
  const handleResetPrizes = async () => {
    // Önce bir onay iste
    const confirmReset = window.confirm('Tüm ödülleri sıfırlamak istediğinizden emin misiniz? Bu işlem geri alınamaz.');
    
    if (!confirmReset) {
      return;
    }
    
    // Şifre modalını göster
    setPasswordAction('resetPrizes');
    setShowPasswordModal(true);
  };
  
  const confirmPasswordAction = async () => {
    try {
      if (passwordAction === 'clearParticipants') {
        setClearing(true);
        
        // Katılımcıları sil
        await deleteAllParticipants();
        
        // Verileri yenile
        await refreshParticipants();
        
        alert('Tüm katılımcılar başarıyla silindi.');
        setClearing(false);
      } 
      else if (passwordAction === 'resetPrizes') {
        setResettingPrizes(true);
        
        // Ödülleri sıfırla
        const result = await resetPrizes();
        
        if (result.success) {
          alert('Tüm ödüller başarıyla sıfırlandı.');
        } else {
          alert(`Ödüller sıfırlanırken bir hata oluştu: ${result.error}`);
        }
        
        setResettingPrizes(false);
      }
    } catch (error) {
      console.error('İşlem hatası:', error);
      alert(`İşlem sırasında bir hata oluştu: ${error.message}`);
      setClearing(false);
      setResettingPrizes(false);
    }
  };

  const loading = participantsLoading || prizesLoading;
  const error = participantsError || prizesError;

  return (
    <div className="container">
      <div className="header">
        <h1>ReactXchem Çekiliş Yönetimi</h1>
      </div>

      <div className="card">
        <h2>Yönetim Paneli</h2>

        {error && <div className="error">{error}</div>}

        <div style={{ marginBottom: '20px', display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
          <button
            className="btn"
            onClick={handleRefresh}
            disabled={refreshing || loading}
          >
            {refreshing ? 'Yenileniyor...' : 'Verileri Yenile'}
          </button>

          <Link to="/qrcode" className="btn">
            QR Kod Oluştur
          </Link>

          <Link to="/draw" className="btn btn-accent">
            Çekilişi Başlat
          </Link>
          
          <Link to="/prize-management" className="btn" style={{ background: '#28a745', color: 'white' }}>
            Ödül Yönetimi
          </Link>
          
          <button
            className="btn"
            onClick={handleClearParticipants}
            disabled={clearing || loading}
            style={{ background: '#dc3545', color: 'white' }}
          >
            {clearing ? 'Temizleniyor...' : 'Katılımcıları Temizle'}
          </button>
          
          <button
            className="btn"
            onClick={handleResetPrizes}
            disabled={resettingPrizes || loading}
            style={{ background: '#ff9800', color: 'white' }}
          >
            {resettingPrizes ? 'Ödüller Sıfırlanıyor...' : 'Ödülleri Sıfırla'}
          </button>
        </div>

        <div className="card">
          <h3>Ödül Listesi</h3>
          {loading ? (
            <p>Ödüller yükleniyor...</p>
          ) : (
            <ul>
              {prizes.map((prize) => (
                <li key={prize.id} className="prize-card">
                  <h4 className="prize-title">{prize.name}</h4>
                  <p className="sponsor-name">Sponsor: {prize.sponsor}</p>
                  <p className="quantity">Kazanan Sayısı: {prize.quantity}</p>
                </li>
              ))}
            </ul>
          )}
        </div>

        <div className="card">
          <h3>Katılımcı Listesi</h3>
          {loading ? (
            <p>Katılımcılar yükleniyor...</p>
          ) : (
            <>
              <ExportParticipants participants={participants} />
              <ParticipantList participants={participants} />
            </>
          )}
        </div>
      </div>
      
      <PasswordModal 
        isOpen={showPasswordModal}
        onClose={() => setShowPasswordModal(false)}
        onConfirm={confirmPasswordAction}
        title={passwordAction === 'clearParticipants' ? 'Katılımcıları Temizle' : 'Ödülleri Sıfırla'}
        message={passwordAction === 'clearParticipants' 
          ? 'Tüm katılımcı verilerini silmek için lütfen admin şifresini girin. Bu işlem geri alınamaz!' 
          : 'Tüm ödülleri sıfırlamak için lütfen admin şifresini girin. Bu işlem geri alınamaz!'}
      />
    </div>
  );
};

export default AdminPage;