import React from 'react';
import { HashRouter as Router, Route, Routes } from 'react-router-dom';
import RegistrationPage from './pages/RegistrationPage';
import AdminPage from './pages/AdminPage';
import QRCodePage from './pages/QRCodePage';
import DrawPage from './pages/DrawPage';
import PrizeManagementPage from './pages/PrizeManagementPage';
import { ParticipantProvider } from './context/ParticipantContext';
import { PrizeProvider } from './context/PrizeContext';
import './styles/PrizeManagement.css';

function App() {
  return (
    <Router>
      <ParticipantProvider>
        <PrizeProvider>
          <Routes>
            <Route path="/" element={<RegistrationPage />} />
            <Route path="/admin" element={<AdminPage />} />
            <Route path="/qrcode" element={<QRCodePage />} />
            <Route path="/draw" element={<DrawPage />} />
            <Route path="/prize-management" element={<PrizeManagementPage />} />
            <Route path="/prize-management/:id" element={<PrizeManagementPage />} />
          </Routes>
        </PrizeProvider>
      </ParticipantProvider>
    </Router>
  );
}

export default App;