import React, { useState, useContext, useEffect, useCallback, useMemo } from 'react';
import { Link, useNavigate, useParams } from 'react-router-dom';
import { PrizeContext } from '../context/PrizeContext';
import PasswordModal from '../components/modals/PasswordModal';

const PrizeManagementPage = () => {
  const { prizes, loading, error, addPrize, updatePrize, deletePrize, getPrize, refreshPrizes } = useContext(PrizeContext);
  const navigate = useNavigate();
  const { id } = useParams(); // Eğer düzenleme modunda ise id parametresi mevcut olacak
  
  const [formData, setFormData] = useState({
    name: '',
    sponsor: '',
    quantity: 1,
    imageUrl: '',
    description: '',
    category: '',
    priority: 1
  });
  
  const [isEditMode, setIsEditMode] = useState(false);
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [passwordAction, setPasswordAction] = useState('');
  const [validationErrors, setValidationErrors] = useState({});
  const [actionLoading, setActionLoading] = useState(false);
  const [successMessage, setSuccessMessage] = useState('');
  
  // Eğer id parametresi varsa, ödül verisini getir
  useEffect(() => {
    const fetchPrizeData = async () => {
      if (id) {
        setActionLoading(true);
        const result = await getPrize(id);
        setActionLoading(false);
        
        if (result.success) {
          setFormData(result.prize);
          setIsEditMode(true);
        } else {
          alert('Ödül bulunamadı: ' + result.error);
          navigate('/prize-management');
        }
      }
    };
    
    fetchPrizeData();
  }, [id, navigate]); // getPrize bağımlılığını kaldırdık
  
  useEffect(() => {
    // Başarı mesajını 3 saniye sonra kaldır
    if (successMessage) {
      const timer = setTimeout(() => {
        setSuccessMessage('');
      }, 3000);
      
      return () => clearTimeout(timer);
    }
  }, [successMessage]);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    let processedValue = value;
    
    // Sayısal alanları integer'a dönüştür
    if (name === 'quantity' || name === 'priority') {
      processedValue = parseInt(value) || 0;
    }
    
    setFormData({
      ...formData,
      [name]: processedValue
    });
    
    // Validasyon hatasını temizle
    if (validationErrors[name]) {
      setValidationErrors({
        ...validationErrors,
        [name]: ''
      });
    }
  };
  
  const validateForm = useCallback(() => {
    const errors = {};
    
    if (!formData.name || !formData.name.trim()) {
      errors.name = 'Ödül adı zorunludur';
    }
    
    if (!formData.sponsor || !formData.sponsor.trim()) {
      errors.sponsor = 'Sponsor adı zorunludur';
    }
    
    if (formData.quantity < 1) {
      errors.quantity = 'Ödül miktarı en az 1 olmalıdır';
    }
    
    if (!formData.description || !formData.description.trim()) {
      errors.description = 'Açıklama zorunludur';
    }
    
    if (!formData.category || !formData.category.trim()) {
      errors.category = 'Kategori zorunludur';
    }
    
    if (formData.priority < 1) {
      errors.priority = 'Öncelik değeri en az 1 olmalıdır';
    }
    
    setValidationErrors(errors);
    return Object.keys(errors).length === 0;
  }, [formData]);
  
  const handleFormSubmit = useCallback((e) => {
    e.preventDefault();
    
    if (!validateForm()) {
      return;
    }
    
    // İşlem öncesi şifre doğrulaması gerçekleştir
    setPasswordAction(isEditMode ? 'updatePrize' : 'addPrize');
    setShowPasswordModal(true);
  }, [isEditMode, validateForm]);
  
  const handleDelete = useCallback(() => {
    if (window.confirm('Bu ödülü silmek istediğinizden emin misiniz? Bu işlem geri alınamaz.')) {
      setPasswordAction('deletePrize');
      setShowPasswordModal(true);
    }
  }, []);
  
  const confirmPasswordAction = async () => {
    setActionLoading(true);
    
    try {
      if (passwordAction === 'addPrize') {
        const result = await addPrize(formData);
        
        if (result.success) {
          setFormData({
            name: '',
            sponsor: '',
            quantity: 1,
            imageUrl: '',
            description: '',
            category: '',
            priority: 1
          });
          setSuccessMessage('Ödül başarıyla eklendi');
        } else {
          alert('Ödül eklenirken bir hata oluştu: ' + result.error);
        }
      } 
      else if (passwordAction === 'updatePrize') {
        const result = await updatePrize(id, formData);
        
        if (result.success) {
          setSuccessMessage('Ödül başarıyla güncellendi');
        } else {
          alert('Ödül güncellenirken bir hata oluştu: ' + result.error);
        }
      }
      else if (passwordAction === 'deletePrize') {
        const result = await deletePrize(id);
        
        if (result.success) {
          alert('Ödül başarıyla silindi');
          navigate('/admin');
        } else {
          alert('Ödül silinirken bir hata oluştu: ' + result.error);
        }
      }
    } catch (error) {
      alert('İşlem sırasında bir hata oluştu: ' + error.message);
    } finally {
      setActionLoading(false);
      setShowPasswordModal(false);
    }
  };
  
  // Bu sürekli yeniden oluşturma sorununu önler
  const memoizedPrizes = useMemo(() => {
    return prizes.map(prize => (
      <div key={prize.id} className="prize-card">
        <div className="prize-header">
          <h3>{prize.name}</h3>
          <span className="prize-category">{prize.category || 'Kategori Yok'}</span>
        </div>
        
        <div className="prize-body">
          <p><strong>Sponsor:</strong> {prize.sponsor}</p>
          <p><strong>Miktar:</strong> {prize.quantity}</p>
          <p><strong>Öncelik:</strong> {prize.priority || 1}</p>
          <p>{prize.description || 'Açıklama yok'}</p>
          
          {prize.imageUrl && (
            <div className="prize-image">
              <img src={prize.imageUrl} alt={prize.name} />
            </div>
          )}
        </div>
        
        <div className="prize-footer">
          <Link to={`/prize-management/${prize.id}`} className="btn btn-small">
            Düzenle
          </Link>
        </div>
      </div>
    ));
  }, [prizes]);
  
  if (loading && !id) {
    return (
      <div className="container">
        <div className="header">
          <h1>Ödül Yönetimi</h1>
        </div>
        <div className="card">
          <p>Yükleniyor...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="container">
      <div className="header">
        <h1>{isEditMode ? 'Ödül Düzenle' : 'Yeni Ödül Ekle'}</h1>
      </div>

      <div className="card">
        <nav style={{ marginBottom: '20px' }}>
          <Link to="/admin" className="btn">Ana Sayfaya Dön</Link>
          {isEditMode && (
            <Link to="/prize-management" className="btn" style={{ marginLeft: '10px' }}>
              Yeni Ödül Ekle
            </Link>
          )}
        </nav>
        
        {error && <div className="error">{error}</div>}
        {successMessage && <div className="success-message">{successMessage}</div>}
        
        <form onSubmit={handleFormSubmit}>
          <div className="form-group">
            <label htmlFor="name">Ödül Adı *</label>
            <input
              type="text"
              id="name"
              name="name"
              value={formData.name}
              onChange={handleInputChange}
              className={validationErrors.name ? 'error-input' : ''}
            />
            {validationErrors.name && <div className="error-text">{validationErrors.name}</div>}
          </div>
          
          <div className="form-group">
            <label htmlFor="sponsor">Sponsor *</label>
            <input
              type="text"
              id="sponsor"
              name="sponsor"
              value={formData.sponsor}
              onChange={handleInputChange}
              className={validationErrors.sponsor ? 'error-input' : ''}
            />
            {validationErrors.sponsor && <div className="error-text">{validationErrors.sponsor}</div>}
          </div>
          
          <div className="form-group">
            <label htmlFor="quantity">Miktar *</label>
            <input
              type="number"
              id="quantity"
              name="quantity"
              value={formData.quantity}
              onChange={handleInputChange}
              min="1"
              className={validationErrors.quantity ? 'error-input' : ''}
            />
            {validationErrors.quantity && <div className="error-text">{validationErrors.quantity}</div>}
          </div>
          
          <div className="form-group">
            <label htmlFor="imageUrl">Görsel URL</label>
            <input
              type="text"
              id="imageUrl"
              name="imageUrl"
              value={formData.imageUrl}
              onChange={handleInputChange}
              placeholder="https://example.com/image.jpg"
            />
          </div>
          
          <div className="form-group">
            <label htmlFor="description">Açıklama *</label>
            <textarea
              id="description"
              name="description"
              value={formData.description}
              onChange={handleInputChange}
              rows="3"
              className={validationErrors.description ? 'error-input' : ''}
            />
            {validationErrors.description && <div className="error-text">{validationErrors.description}</div>}
          </div>
          
          <div className="form-group">
            <label htmlFor="category">Kategori *</label>
            <input
              type="text"
              id="category"
              name="category"
              value={formData.category}
              onChange={handleInputChange}
              className={validationErrors.category ? 'error-input' : ''}
              placeholder="Örn: Elektronik, Giyim, Eğitim"
            />
            {validationErrors.category && <div className="error-text">{validationErrors.category}</div>}
          </div>
          
          <div className="form-group">
            <label htmlFor="priority">Öncelik Değeri *</label>
            <input
              type="number"
              id="priority"
              name="priority"
              value={formData.priority}
              onChange={handleInputChange}
              min="1"
              max="10"
              className={validationErrors.priority ? 'error-input' : ''}
            />
            <small>1 (düşük) - 10 (yüksek) arasında değer giriniz</small>
            {validationErrors.priority && <div className="error-text">{validationErrors.priority}</div>}
          </div>
          
          <div className="form-buttons">
            <button 
              type="submit" 
              className="btn btn-accent"
              disabled={actionLoading}
            >
              {actionLoading ? 'İşlem Yapılıyor...' : isEditMode ? 'Ödülü Güncelle' : 'Ödül Ekle'}
            </button>
            
            {isEditMode && (
              <button
                type="button"
                className="btn"
                onClick={handleDelete}
                disabled={actionLoading}
                style={{ background: '#dc3545', color: 'white', marginLeft: '10px' }}
              >
                Ödülü Sil
              </button>
            )}
          </div>
        </form>
      </div>
      
      <div className="card" style={{ marginTop: '20px' }}>
        <h2>Mevcut Ödüller</h2>
        
        <div className="prize-list">
          {prizes.length === 0 ? (
            <p>Henüz ödül bulunmuyor.</p>
          ) : (
            <div className="prize-grid">
              {memoizedPrizes}
            </div>
          )}
        </div>
      </div>
      
      <PasswordModal
        isOpen={showPasswordModal}
        onClose={() => setShowPasswordModal(false)}
        onConfirm={confirmPasswordAction}
        title={
          passwordAction === 'addPrize' ? 'Ödül Ekle' : 
          passwordAction === 'updatePrize' ? 'Ödül Güncelle' :
          'Ödül Sil'
        }
        message={
          passwordAction === 'addPrize' ? 'Ödül eklemek için lütfen admin şifresini girin.' : 
          passwordAction === 'updatePrize' ? 'Ödülü güncellemek için lütfen admin şifresini girin.' :
          'Ödülü silmek için lütfen admin şifresini girin. Bu işlem geri alınamaz!'
        }
      />
    </div>
  );
};

export default PrizeManagementPage;