import React from 'react';
import * as XLSX from 'xlsx';
import { saveAs } from 'file-saver';
import jsPDF from 'jspdf';
import 'jspdf-autotable';

const ExportParticipants = ({ participants }) => {
  // CSV olarak dışa aktarma
  const exportAsCSV = () => {
    if (!participants || participants.length === 0) {
      alert('Dışa aktarılacak katılımcı bulunmamaktadır.');
      return;
    }

    // Her katılımcının verilerini düzenle
    const participantsData = participants.map(participant => {
      // Tarih formatını düzenle
      let registrationTime = '';
      if (participant.registrationTime instanceof Date) {
        registrationTime = participant.registrationTime.toLocaleString('tr-TR');
      } else if (participant.registrationTime?.toDate) {
        registrationTime = participant.registrationTime.toDate().toLocaleString('tr-TR');
      }

      return {
        'Ad': participant.firstName || '',
        'Soyad': participant.lastName || '',
        'E-posta': participant.email || '',
        'Kayıt Zamanı': registrationTime,
        'Kazanan': participant.isWinner ? 'Evet' : 'Hayır',
        'Ödül': participant.prize || ''
      };
    });

    // CSV verilerini oluştur
    const worksheet = XLSX.utils.json_to_sheet(participantsData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Katılımcılar');
    
    // CSV dosyasını oluştur ve indir
    const csvData = XLSX.write(workbook, { bookType: 'csv', type: 'array' });
    const blob = new Blob([csvData], { type: 'text/csv;charset=utf-8' });
    
    // Dosya adını tarih ile oluştur
    const date = new Date().toISOString().slice(0, 10);
    saveAs(blob, `katilimcilar-${date}.csv`);
  };

  // Excel olarak dışa aktarma
  const exportAsExcel = () => {
    if (!participants || participants.length === 0) {
      alert('Dışa aktarılacak katılımcı bulunmamaktadır.');
      return;
    }

    // Her katılımcının verilerini düzenle
    const participantsData = participants.map(participant => {
      // Tarih formatını düzenle
      let registrationTime = '';
      if (participant.registrationTime instanceof Date) {
        registrationTime = participant.registrationTime.toLocaleString('tr-TR');
      } else if (participant.registrationTime?.toDate) {
        registrationTime = participant.registrationTime.toDate().toLocaleString('tr-TR');
      }

      return {
        'Ad': participant.firstName || '',
        'Soyad': participant.lastName || '',
        'E-posta': participant.email || '',
        'Kayıt Zamanı': registrationTime,
        'Kazanan': participant.isWinner ? 'Evet' : 'Hayır',
        'Ödül': participant.prize || ''
      };
    });

    // Excel verilerini oluştur
    const worksheet = XLSX.utils.json_to_sheet(participantsData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Katılımcılar');
    
    // Excel dosyasını oluştur ve indir
    const excelData = XLSX.write(workbook, { bookType: 'xlsx', type: 'array' });
    const blob = new Blob([excelData], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    
    // Dosya adını tarih ile oluştur
    const date = new Date().toISOString().slice(0, 10);
    saveAs(blob, `katilimcilar-${date}.xlsx`);
  };

  // PDF olarak dışa aktarma
  const exportAsPDF = () => {
    if (!participants || participants.length === 0) {
      alert('Dışa aktarılacak katılımcı bulunmamaktadır.');
      return;
    }

    // PDF oluştur
    const doc = new jsPDF();
    
    // Başlık ekle
    const date = new Date().toLocaleDateString('tr-TR');
    doc.setFontSize(18);
    doc.text('Çekiliş Katılımcı Listesi', 14, 22);
    
    doc.setFontSize(11);
    doc.text(`Oluşturulma Tarihi: ${date}`, 14, 30);
    doc.text(`Toplam Katılımcı Sayısı: ${participants.length}`, 14, 38);
    
    // Tablo verilerini hazırla
    const tableColumn = ["Ad", "Soyad", "E-posta", "Kayıt Zamanı", "Kazanan", "Ödül"];
    const tableRows = [];
    
    participants.forEach(participant => {
      // Tarih formatını düzenle
      let registrationTime = '';
      if (participant.registrationTime instanceof Date) {
        registrationTime = participant.registrationTime.toLocaleString('tr-TR');
      } else if (participant.registrationTime?.toDate) {
        registrationTime = participant.registrationTime.toDate().toLocaleString('tr-TR');
      }
      
      const participantData = [
        participant.firstName || '',
        participant.lastName || '',
        participant.email || '',
        registrationTime,
        participant.isWinner ? 'Evet' : 'Hayır',
        participant.prize || ''
      ];
      tableRows.push(participantData);
    });
    
    // Tablo oluştur
    doc.autoTable({
      head: [tableColumn],
      body: tableRows,
      startY: 45,
      styles: {
        fontSize: 10,
        cellPadding: 3,
        overflow: 'linebreak',
        halign: 'left'
      },
      columnStyles: {
        0: { cellWidth: 25 },
        1: { cellWidth: 25 },
        2: { cellWidth: 45 },
        3: { cellWidth: 35 },
        4: { cellWidth: 20 },
        5: { cellWidth: 30 }
      }
    });
    
    // PDF dosyasını indir
    doc.save(`katilimcilar-${date.replace(/\//g, '-')}.pdf`);
  };

  return (
    <div style={{ marginBottom: '20px', display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
      <button 
        onClick={exportAsCSV}
        className="btn"
        style={{ background: '#4CAF50', color: 'white' }}
      >
        CSV Olarak İndir
      </button>
      
      <button 
        onClick={exportAsExcel}
        className="btn"
        style={{ background: '#2196F3', color: 'white' }}
      >
        Excel Olarak İndir
      </button>
      
      <button 
        onClick={exportAsPDF}
        className="btn"
        style={{ background: '#FF5722', color: 'white' }}
      >
        PDF Olarak İndir
      </button>
    </div>
  );
};

export default ExportParticipants;