// İşlemleri sonuçlarını tutarlı hale getirmek için standart bir yanıt formatı
const createResponse = (success, data = null, error = null) => {
  return { 
    success: success, 
    ...(data && { ...data }), 
    ...(error && { error }) 
  };
};

export const PrizeProvider = ({ children }) => {
  const [prizes, setPrizes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // İlk yüklemede ödülleri getir
  useEffect(() => {
    const fetchPrizes = async () => {
      try {
        const querySnapshot = await getDocs(collection(db, 'prizes'));
        
        console.log('Bulunan ödül sayısı:', querySnapshot.size);
        
        // Eğer veritabanında ödül yoksa, varsayılan ödülleri ekle
        if (querySnapshot.empty) {
          console.log('Veritabanında ödül bulunamadı, varsayılan ödüller ekleniyor...');
          const prizesPromises = DEFAULT_PRIZES.map(prize => 
            addDoc(collection(db, 'prizes'), prize)
          );
          
          await Promise.all(prizesPromises);
          
          // Eklenen ödülleri tekrar getir
          const newQuerySnapshot = await getDocs(collection(db, 'prizes'));
          console.log('Yeniden eklenen ödül sayısı:', newQuerySnapshot.size);
          const prizeList = newQuerySnapshot.docs.map(doc => {
            const data = doc.data();
            console.log(`Eklenen ödül: ${doc.id}`, data);
            return {
              id: doc.id,
              ...data
            };
          });
          
          setPrizes(prizeList);
        } else {
          console.log('Veritabanından ödüller başarıyla getirildi');
          const prizeList = querySnapshot.docs.map(doc => {
            const data = doc.data();
            console.log(`Ödül: ${doc.id}`, data);
            return {
              id: doc.id,
              ...data
            };
          });
          
          console.log('İşlenmiş ödül listesi:', prizeList);
          
          setPrizes(prizeList);
        }
        
        setLoading(false);
      } catch (err) {
        console.error('Ödüller yüklenirken hata oluştu:', err);
        setError('Ödüller yüklenirken bir hata oluştu.');
        setLoading(false);
      }
    };

    fetchPrizes();
    // Boş bağımlılık listesi - sadece mount olunca çalışır
  }, []);

  // Ödül güncelleme işlevi - useCallback ile optimize edildi
  const updatePrize = useCallback(async (id, data) => {
    try {
      const prizeRef = doc(db, 'prizes', id);
      await updateDoc(prizeRef, data);
      
      setPrizes(prizes.map(prize => 
        prize.id === id ? { ...prize, ...data } : prize
      ));
      
      return createResponse(true);
    } catch (err) {
      console.error('Ödül güncellenirken hata oluştu:', err);
      setError('Ödül güncellenirken bir hata oluştu.');
      return createResponse(false, null, err.message);
    }
  }, [prizes]);

  // Veritabanından ödülleri yeniden yükleme işlevi - useCallback ile optimize edildi
  const refreshPrizes = useCallback(async () => {
    setLoading(true);
    try {
      const querySnapshot = await getDocs(collection(db, 'prizes'));
      const prizeList = querySnapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));
      
      setPrizes(prizeList);
      setLoading(false);
      return createResponse(true);
    } catch (err) {
      console.error('Ödüller yenilenirken hata oluştu:', err);
      setError('Ödüller yenilenirken bir hata oluştu.');
      setLoading(false);
      return createResponse(false, null, err.message);
    }
  }, []);

  // Yeni ödül ekleme fonksiyonu - useCallback ile optimize edildi
  const addPrize = useCallback(async (prizeData) => {
    setLoading(true);
    setError(null);
    try {
      console.log('Yeni ödül ekleniyor:', prizeData);
      
      const newPrize = {
        ...prizeData,
        winners: []
      };
      
      const docRef = await addDoc(collection(db, 'prizes'), newPrize);
      console.log('Ödül başarıyla eklendi, ID:', docRef.id);
      
      // State güncelleme
      setPrizes(prevPrizes => [...prevPrizes, {
        id: docRef.id,
        ...newPrize
      }]);
      
      setLoading(false);
      return createResponse(true, { id: docRef.id, message: 'Ödül başarıyla eklendi.' });
    } catch (error) {
      console.error('Ödül ekleme hatası:', error);
      setError('Ödül eklenirken bir hata oluştu.');
      setLoading(false);
      return createResponse(false, null, error.message);
    }
  }, []);
  
  // Ödül silme fonksiyonu - useCallback ile optimize edildi
  const deletePrize = useCallback(async (id) => {
    setLoading(true);
    setError(null);
    try {
      console.log('Ödül siliniyor, ID:', id);
      
      await deleteDoc(doc(db, 'prizes', id));
      console.log('Ödül başarıyla silindi');
      
      // State güncelleme
      setPrizes(prevPrizes => prevPrizes.filter(prize => prize.id !== id));
      
      setLoading(false);
      return createResponse(true, { message: 'Ödül başarıyla silindi.' });
    } catch (error) {
      console.error('Ödül silme hatası:', error);
      setError('Ödül silinirken bir hata oluştu.');
      setLoading(false);
      return createResponse(false, null, error.message);
    }
  }, []);
  
  // Tek bir ödülü getirme fonksiyonu - useCallback ile optimize edildi
  const getPrize = useCallback(async (id) => {
    // Bu fonksiyon her çağrıldığında global state'i güncellemesin
    // sadece yerel durum döndürsün
    try {
      // Aynı ID için zaten hafızada varsa, direkt döndür
      const existingPrize = prizes.find(prize => prize.id === id);
      if (existingPrize) {
        return createResponse(true, { prize: existingPrize });
      }
      
      const prizeDoc = await getDoc(doc(db, 'prizes', id));
      
      if (!prizeDoc.exists()) {
        return createResponse(false, null, 'Ödül bulunamadı.');
      }
      
      const prizeData = {
        id: prizeDoc.id,
        ...prizeDoc.data()
      };
      
      return createResponse(true, { prize: prizeData });
    } catch (error) {
      console.error('Ödül getirme hatası:', error);
      return createResponse(false, null, error.message);
    }
  }, [prizes]);

  // Tüm ödülleri temizle ve varsayılan ödülleri tekrar ekle - useCallback ile optimize edildi
  const resetPrizes = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      console.log('Ödülleri sıfırlama işlemi başlatılıyor...');
      
      // Mevcut tüm ödülleri al
      const querySnapshot = await getDocs(collection(db, 'prizes'));
      console.log('Silinecek ödül sayısı:', querySnapshot.size);
      
      // Her ödülü sil
      const deletePromises = querySnapshot.docs.map(docSnapshot => {
        console.log(`Siliniyor: ${docSnapshot.id}`);
        return deleteDoc(doc(db, 'prizes', docSnapshot.id));
      });
      
      await Promise.all(deletePromises);
      console.log('Tüm ödüller silindi');
      
      // Varsayılan ödülleri ekle
      const addPromises = DEFAULT_PRIZES.map(prize => 
        addDoc(collection(db, 'prizes'), prize)
      );
      
      const addResults = await Promise.all(addPromises);
      console.log('Varsayılan ödüller eklendi:', addResults.length, 'adet');
      
      // Ödülleri tekrar getir
      const refreshedSnapshot = await getDocs(collection(db, 'prizes'));
      const prizeList = refreshedSnapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));
      
      console.log('Ödüller başarıyla sıfırlandı, yeni liste:', prizeList);
      setPrizes(prizeList);
      setLoading(false);
      return createResponse(true, { message: 'Ödüller başarıyla sıfırlandı.' });
    } catch (error) {
      console.error('Ödülleri sıfırlama hatası:', error);
      setError('Ödülleri sıfırlarken bir hata oluştu.');
      setLoading(false);
      return createResponse(false, null, error.message);
    }
  }, []);

  return (
    <PrizeContext.Provider value={{
      prizes,
      loading,
      error,
      addPrize,
      updatePrize,
      deletePrize,
      getPrize,
      refreshPrizes,
      resetPrizes
    }}>
      {children}
    </PrizeContext.Provider>
  );
};
