import React, { useState, useContext, useEffect } from 'react';
import { ParticipantContext } from '../context/ParticipantContext';

const ParticipantList = ({ participants: initialParticipants }) => {
  const { deleteParticipant } = useContext(ParticipantContext);
  const [participants, setParticipants] = useState(initialParticipants);
  const [sortField, setSortField] = useState('firstName');
  const [sortDirection, setSortDirection] = useState('asc');
  const [searchTerm, setSearchTerm] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const participantsPerPage = 10;

  // Props değiştiğinde state'i güncelle (componentDidUpdate benzeri)
  useEffect(() => {
    setParticipants(initialParticipants);
  }, [initialParticipants]);

  // Katılımcıları sırala
  const sortParticipants = (field) => {
    if (field === sortField) {
      // Aynı alan seçilirse yönü değiştir
      setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc');
    } else {
      // Farklı alan seçilirse, yeni alanı ayarla ve yönü artan olarak başlat
      setSortField(field);
      setSortDirection('asc');
    }
  };

  // Katılımcıyı sil
  const handleDelete = async (id) => {
    if (window.confirm('Bu katılımcıyı çekilişten silmek istediğinize emin misiniz?')) {
      const result = await deleteParticipant(id);
      if (result.success) {
        // State'i güncelle
        setParticipants(participants.filter(p => p.id !== id));
      } else {
        alert(`Silme işlemi başarısız: ${result.error}`);
      }
    }
  };

  // Sıralanmış katılımcılar
  const sortedParticipants = [...participants].sort((a, b) => {
    // Null değerleri kontrol et
    if (a[sortField] === null || a[sortField] === undefined) return 1;
    if (b[sortField] === null || b[sortField] === undefined) return -1;
    
    // Karşılaştırma işlemi
    let comparison = 0;
    if (typeof a[sortField] === 'string') {
      comparison = a[sortField].localeCompare(b[sortField], 'tr-TR');
    } else {
      comparison = a[sortField] > b[sortField] ? 1 : -1;
    }
    
    // Sıralama yönüne göre sonucu döndür
    return sortDirection === 'asc' ? comparison : -comparison;
  });

  const filteredParticipants = sortedParticipants.filter(participant => {
    const fullName = `${participant.firstName} ${participant.lastName}`.toLowerCase();
    const email = participant.email ? participant.email.toLowerCase() : '';
    const search = searchTerm.toLowerCase();
    
    return fullName.includes(search) || email.includes(search);
  });

  // Sayfalandırma için indeksleri hesapla
  const indexOfLastParticipant = currentPage * participantsPerPage;
  const indexOfFirstParticipant = indexOfLastParticipant - participantsPerPage;
  const currentParticipants = filteredParticipants.slice(indexOfFirstParticipant, indexOfLastParticipant);
  
  // Toplam sayfa sayısını hesapla
  const totalPages = Math.ceil(filteredParticipants.length / participantsPerPage);

  // Sayfa değiştirme fonksiyonu
  const paginate = (pageNumber) => setCurrentPage(pageNumber);

  // Arama terimini değiştirme
  const handleSearchChange = (e) => {
    setSearchTerm(e.target.value);
    setCurrentPage(1); // Arama yapıldığında ilk sayfaya dön
  };

  return (
    <div>
      <div className="form-group">
        <input
          type="text"
          className="form-control"
          placeholder="Ad, soyad veya e-posta ile ara..."
          value={searchTerm}
          onChange={handleSearchChange}
        />
      </div>

      {filteredParticipants.length === 0 ? (
        <p>Katılımcı bulunamadı.</p>
      ) : (
        <>
          <p>Toplam Katılımcı: {filteredParticipants.length}</p>
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ borderBottom: '1px solid #ccc' }}>
                <th 
                  style={{ padding: '8px', textAlign: 'left', cursor: 'pointer' }}
                  onClick={() => sortParticipants('firstName')}
                >
                  Ad {sortField === 'firstName' && (sortDirection === 'asc' ? '▲' : '▼')}
                </th>
                <th 
                  style={{ padding: '8px', textAlign: 'left', cursor: 'pointer' }}
                  onClick={() => sortParticipants('lastName')}
                >
                  Soyad {sortField === 'lastName' && (sortDirection === 'asc' ? '▲' : '▼')}
                </th>
                <th style={{ padding: '8px', textAlign: 'left' }}>E-posta</th>
                <th 
                  style={{ padding: '8px', textAlign: 'left', cursor: 'pointer' }}
                  onClick={() => sortParticipants('registrationTime')}
                >
                  Kayıt Zamanı {sortField === 'registrationTime' && (sortDirection === 'asc' ? '▲' : '▼')}
                </th>
                <th style={{ padding: '8px', textAlign: 'left' }}>Kazanan</th>
                <th style={{ padding: '8px', textAlign: 'left' }}>Ödül</th>
                <th style={{ padding: '8px', textAlign: 'center' }}>İşlemler</th>
              </tr>
            </thead>
            <tbody>
              {currentParticipants.map((participant) => (
                <tr 
                  key={participant.id} 
                  style={{ 
                    borderBottom: '1px solid #eee',
                    backgroundColor: participant.isWinner ? '#e1f5fe' : 'inherit'
                  }}
                >
                  <td style={{ padding: '8px' }}>{participant.firstName}</td>
                  <td style={{ padding: '8px' }}>{participant.lastName}</td>
                  <td style={{ padding: '8px' }}>{participant.email}</td>
                  <td style={{ padding: '8px' }}>
                    {participant.registrationTime instanceof Date
                      ? participant.registrationTime.toLocaleString('tr-TR')
                      : participant.registrationTime?.toDate?.().toLocaleString('tr-TR') || '-'}
                  </td>
                  <td style={{ padding: '8px' }}>
                    {participant.isWinner ? '✅' : '❌'}
                  </td>
                  <td style={{ padding: '8px' }}>
                    {participant.prize || '-'}
                  </td>
                  <td style={{ padding: '8px', textAlign: 'center' }}>
                    <button 
                      onClick={() => handleDelete(participant.id)}
                      style={{ 
                        backgroundColor: '#f44336', 
                        color: 'white', 
                        border: 'none', 
                        borderRadius: '4px',
                        padding: '4px 8px',
                        cursor: 'pointer'
                      }}
                    >
                      Sil
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>

          {/* Sayfalandırma */}
          {totalPages > 1 && (
            <div style={{ display: 'flex', justifyContent: 'center', margin: '20px 0' }}>
              <button
                onClick={() => paginate(currentPage - 1)}
                disabled={currentPage === 1}
                className="btn"
                style={{ marginRight: '10px' }}
              >
                Önceki
              </button>
              
              <span style={{ margin: '0 10px', lineHeight: '36px' }}>
                Sayfa {currentPage} / {totalPages}
              </span>
              
              <button
                onClick={() => paginate(currentPage + 1)}
                disabled={currentPage === totalPages}
                className="btn"
                style={{ marginLeft: '10px' }}
              >
                Sonraki
              </button>
            </div>
          )}
        </>
      )}
    </div>
  );
};

export default ParticipantList;