/**
 * Uygulama için merkezi günlük (log) yönetim sistemi
 * Üretim ortamında hassas logların engellenmesini sağlar
 */

// Ortam kontrolü
const isProduction = process.env.NODE_ENV === 'production';

// Log seviyelerini tanımla
export const LOG_LEVELS = {
  DEBUG: 0,
  INFO: 1,
  WARN: 2,
  ERROR: 3
};

// Minimum log seviyesi (üretim ortamında daha yüksek seviye kullanılabilir)
const MIN_LOG_LEVEL = isProduction ? LOG_LEVELS.WARN : LOG_LEVELS.DEBUG;

/**
 * Formatlanmış zaman damgası oluşturur
 * @returns {string} - "YYYY-MM-DD HH:MM:SS" formatında zaman damgası
 */
const getTimestamp = () => {
  const now = new Date();
  return now.toISOString().replace('T', ' ').substring(0, 19);
};

/**
 * Varsayılan log fonksiyonu
 * @param {string} level - Log seviyesi (DEBUG, INFO, vb.)
 * @param {string} module - Log kaynağı modül adı
 * @param {string} message - Log mesajı
 * @param {any} data - İlave log verileri
 */
const logMessage = (level, module, message, data = null) => {
  // Seviye kontrolü
  if (LOG_LEVELS[level] < MIN_LOG_LEVEL) return;
  
  const timestamp = getTimestamp();
  const formattedMessage = `[${timestamp}] [${level}] [${module}] ${message}`;
  
  switch(level) {
    case 'ERROR':
      console.error(formattedMessage, data ? data : '');
      break;
    case 'WARN':
      console.warn(formattedMessage, data ? data : '');
      break;
    case 'INFO':
      console.info(formattedMessage, data ? data : '');
      break;
    default:
      console.log(formattedMessage, data ? data : '');
  }
};

// Logger nesnesi
export const logger = {
  debug: (module, message, data) => logMessage('DEBUG', module, message, data),
  info: (module, message, data) => logMessage('INFO', module, message, data),
  warn: (module, message, data) => logMessage('WARN', module, message, data),
  error: (module, message, data) => logMessage('ERROR', module, message, data),
  
  // Özel günlük fonksiyonları
  draw: {
    start: (data) => logMessage('INFO', 'DRAW', 'Çekiliş başlatıldı', data),
    complete: (data) => logMessage('INFO', 'DRAW', 'Çekiliş tamamlandı', data),
    error: (message, error) => logMessage('ERROR', 'DRAW', message, error),
    prizeAssigned: (prize, winner) => logMessage('INFO', 'DRAW', 
      `Ödül atandı: "${prize.name}" -> ${winner.firstName} ${winner.lastName}`, { prizeId: prize.id, winnerId: winner.id })
  },
  
  // Firebase işlemleri için logger
  firebase: {
    read: (collection, id) => logMessage('DEBUG', 'FIREBASE', `Veri okunuyor: ${collection}${id ? '/' + id : ''}`),
    write: (collection, id, data) => logMessage('DEBUG', 'FIREBASE', `Veri yazılıyor: ${collection}${id ? '/' + id : ''}`, 
      isProduction ? null : { dataPreview: JSON.stringify(data).substring(0, 100) + '...' }),
    error: (operation, path, error) => logMessage('ERROR', 'FIREBASE', `Hata: ${operation} işlemi başarısız: ${path}`, error)
  }
};

export default logger;
